/* Orchard — Base Styles */
:root {
  --dark: #1d1d1f;
  --gray: #6e6e73;
  --light: #f5f5f7;
  --white: #fff;
  --blue: #0066cc;
  --border: #d2d2d7;
  --radius: 18px;
  --radius-sm: 12px;
  --shadow: 0 4px 24px rgba(0,0,0,.08);
  --max-width: 1200px;
  --nav-height: 48px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }

body {
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Helvetica Neue', sans-serif;
  color: var(--dark);
  background: var(--white);
  line-height: 1.47;
  font-size: 17px;
  letter-spacing: -.022em;
}

img { display: block; max-width: 100%; }
a { color: var(--blue); text-decoration: none; }
a:hover { text-decoration: underline; }
button { cursor: pointer; border: none; background: none; font: inherit; color: inherit; }

/* Ribbon Banner */
.ribbon {
  background: var(--dark);
  color: var(--white);
  text-align: center;
  padding: 12px 16px;
  font-size: 14px;
  letter-spacing: -.01em;
}
.ribbon a { color: #2997ff; }

/* Navigation */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.8);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,.08);
  height: var(--nav-height);
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 32px;
  height: 100%;
  padding: 0 22px;
}

.nav-logo {
  font-size: 21px;
  font-weight: 700;
  color: var(--dark);
  letter-spacing: -.02em;
}
.nav-logo:hover { text-decoration: none; }

.nav-links {
  display: flex;
  gap: 24px;
  align-items: center;
  list-style: none;
}

.nav-links a {
  font-size: 13px;
  color: var(--dark);
  opacity: .8;
  letter-spacing: -.01em;
}
.nav-links a:hover { opacity: 1; text-decoration: none; }

/* Section Common */
.section {
  padding: 80px 22px;
}

.section-light { background: var(--light); }
.section-white { background: var(--white); }

.section-header {
  text-align: center;
  margin-bottom: 48px;
}

.section-title {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -.03em;
  line-height: 1.08;
  color: var(--dark);
}

.section-subtitle {
  font-size: 21px;
  font-weight: 500;
  color: var(--gray);
  margin-top: 8px;
  letter-spacing: -.01em;
}

/* Hero */
.hero {
  text-align: center;
  padding: 80px 22px 60px;
}

.hero-title {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -.035em;
  line-height: 1.07;
}

.hero-subtitle {
  font-size: 24px;
  font-weight: 500;
  color: var(--dark);
  margin-top: 12px;
  letter-spacing: -.01em;
}

.hero-ctas {
  display: flex;
  justify-content: center;
  gap: 20px;
  margin-top: 24px;
  flex-wrap: wrap;
}

.btn {
  display: inline-block;
  padding: 11px 22px;
  border-radius: 24px;
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -.01em;
  transition: all .2s;
}

.btn-primary {
  background: var(--blue);
  color: var(--white);
}
.btn-primary:hover { background: #0077ed; text-decoration: none; }

.btn-outline {
  border: 1px solid var(--blue);
  color: var(--blue);
}
.btn-outline:hover { background: var(--blue); color: var(--white); text-decoration: none; }

.btn-link {
  color: var(--blue);
  padding: 11px 4px;
  font-size: 17px;
}
.btn-link::after { content: ' \203A'; }

/* Product Icon Bar */
.icon-bar-wrap {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.icon-bar-wrap::-webkit-scrollbar { display: none; }

.icon-bar {
  display: flex;
  gap: 28px;
  padding: 20px 22px;
  max-width: var(--max-width);
  margin: 0 auto;
  justify-content: center;
}

.icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
  cursor: pointer;
}

.icon-circle {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  overflow: hidden;
}

.icon-label {
  font-size: 12px;
  color: var(--dark);
  font-weight: 500;
}

/* Product Grid (Homepage) */
.product-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.product-tile {
  border-radius: var(--radius);
  overflow: hidden;
  position: relative;
  min-height: 500px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 48px 32px 40px;
  box-shadow: var(--shadow);
}

.product-tile.warm { background: linear-gradient(135deg, #faf7f2 0%, #f5ede0 100%); }
.product-tile.cool { background: linear-gradient(135deg, #f5f7fa 0%, #e8ecf1 100%); }
.product-tile.pink { background: linear-gradient(135deg, #faf5f7 0%, #f0e4e8 100%); }
.product-tile.blue { background: linear-gradient(135deg, #f4f7fa 0%, #dce8f2 100%); }
.product-tile.green { background: linear-gradient(135deg, #f5faf6 0%, #e0efe4 100%); }
.product-tile.dark { background: linear-gradient(135deg, #2d2d2f 0%, #1d1d1f 100%); color: var(--white); }

.product-tile.dark .tile-tagline { color: rgba(255,255,255,.7); }

.tile-img {
  width: 200px;
  height: 200px;
  border-radius: 50%;
  background: rgba(255,255,255,.5);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 72px;
  margin-bottom: 24px;
}

.product-tile.dark .tile-img { background: rgba(255,255,255,.1); }

.tile-name {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -.025em;
}

.tile-tagline {
  font-size: 17px;
  color: var(--gray);
  margin-top: 6px;
  max-width: 320px;
}

.tile-ctas {
  display: flex;
  gap: 16px;
  margin-top: 18px;
}

.tile-ctas .btn-link {
  font-size: 17px;
  color: var(--blue);
}

.product-tile.dark .tile-ctas .btn-link { color: #2997ff; }

/* Carousel */
.carousel-wrap {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.carousel {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 8px 0 20px;
}
.carousel::-webkit-scrollbar { display: none; }

.carousel-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--white);
  border-radius: var(--radius);
  padding: 28px 24px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  transition: transform .2s;
}
.carousel-card:hover { transform: translateY(-4px); }

.card-badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  color: #e85000;
  letter-spacing: .04em;
  margin-bottom: 8px;
  text-transform: uppercase;
}

.card-img {
  width: 140px;
  height: 140px;
  border-radius: 50%;
  background: var(--light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 56px;
  margin-bottom: 16px;
}

.card-name {
  font-size: 19px;
  font-weight: 600;
  letter-spacing: -.02em;
}

.card-tagline {
  font-size: 14px;
  color: var(--gray);
  margin-top: 4px;
}

.card-price {
  font-size: 15px;
  font-weight: 500;
  margin-top: 10px;
}

.card-monthly {
  font-size: 13px;
  color: var(--gray);
  margin-top: 2px;
}

.card-note {
  font-size: 12px;
  color: var(--gray);
  margin-top: 4px;
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--white);
  box-shadow: 0 2px 12px rgba(0,0,0,.15);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  z-index: 10;
  color: var(--dark);
  opacity: .9;
}
.carousel-arrow:hover { opacity: 1; }
.carousel-arrow.prev { left: -6px; }
.carousel-arrow.next { right: -6px; }

/* Help & Support Cards */
.help-card {
  flex: 0 0 300px;
}

.help-card .card-img {
  background: none;
  font-size: 40px;
  width: 80px;
  height: 80px;
}

/* Audio Promo */
.audio-promo {
  text-align: center;
  margin-bottom: 32px;
  font-size: 15px;
  color: var(--gray);
}

/* Brand Collab */
.collab-banner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 60px 32px;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  border-radius: var(--radius);
  color: var(--white);
  text-align: center;
}

.collab-banner .section-title { color: var(--white); }
.collab-banner .section-subtitle { color: rgba(255,255,255,.7); }

.collab-products {
  display: flex;
  gap: 20px;
  justify-content: center;
  margin-top: 32px;
  flex-wrap: wrap;
}

.collab-card {
  background: rgba(255,255,255,.1);
  border-radius: var(--radius-sm);
  padding: 24px;
  text-align: center;
  width: 180px;
}

/* Savings */
.savings-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.saving-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 28px 24px;
  box-shadow: var(--shadow);
}

.saving-card h3 {
  font-size: 19px;
  font-weight: 600;
  letter-spacing: -.02em;
}

.saving-card p {
  font-size: 14px;
  color: var(--gray);
  margin-top: 6px;
}

/* Quick Links */
.quick-links {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
  justify-content: center;
}

.quick-link {
  padding: 12px 24px;
  background: var(--light);
  border-radius: 24px;
  font-size: 15px;
  color: var(--dark);
  font-weight: 500;
}
.quick-link:hover { background: #e8e8ed; text-decoration: none; }

/* Entertainment Tabs */
.tabs-nav {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}

.tab-btn {
  padding: 10px 24px;
  border-radius: 24px;
  font-size: 15px;
  font-weight: 500;
  color: var(--dark);
  background: transparent;
  border: 1px solid var(--border);
  transition: all .2s;
}

.tab-btn.active,
.tab-btn:hover {
  background: var(--dark);
  color: var(--white);
  border-color: var(--dark);
}

.tab-panel { display: none; }
.tab-panel.active { display: block; }

.entertainment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.ent-card {
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  background: var(--white);
}

.ent-card-img {
  height: 180px;
  background: var(--light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
}

.ent-card-body {
  padding: 16px 20px 20px;
}

.ent-card-body h3 {
  font-size: 17px;
  font-weight: 600;
}

.ent-card-body p {
  font-size: 13px;
  color: var(--gray);
  margin-top: 4px;
}

.ent-card-body .btn-link {
  font-size: 14px;
  margin-top: 8px;
  display: inline-block;
}

/* Sticky Section Nav (Category Pages) */
.section-nav {
  position: sticky;
  top: var(--nav-height);
  z-index: 99;
  background: rgba(255,255,255,.8);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,.08);
  overflow-x: auto;
  scrollbar-width: none;
}
.section-nav::-webkit-scrollbar { display: none; }

.section-nav-inner {
  display: flex;
  gap: 0;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.section-nav a {
  flex-shrink: 0;
  padding: 14px 20px;
  font-size: 13px;
  color: var(--dark);
  font-weight: 500;
  border-bottom: 2px solid transparent;
  transition: all .2s;
}
.section-nav a:hover { color: var(--blue); text-decoration: none; border-color: var(--blue); }

/* Category Hero */
.cat-hero {
  text-align: center;
  padding: 60px 22px 40px;
  background: var(--light);
}

.cat-hero-title {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -.03em;
}

.cat-hero-subtitle {
  font-size: 19px;
  color: var(--gray);
  margin-top: 8px;
}

/* Shopping Guides */
.guides-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.guide-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 32px 28px;
  box-shadow: var(--shadow);
}

.guide-card h3 {
  font-size: 21px;
  font-weight: 600;
  letter-spacing: -.02em;
}

.guide-card p {
  font-size: 14px;
  color: var(--gray);
  margin-top: 6px;
}

.guide-card .btn-link {
  margin-top: 12px;
  display: inline-block;
}

/* Footer */
.footer {
  background: var(--light);
  padding: 60px 22px 40px;
  font-size: 13px;
  color: var(--gray);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-col h4 {
  font-size: 13px;
  font-weight: 600;
  color: var(--dark);
  margin-bottom: 12px;
}

.footer-col ul {
  list-style: none;
}

.footer-col li { margin-bottom: 8px; }

.footer-col a {
  color: var(--gray);
  font-size: 13px;
}
.footer-col a:hover { color: var(--dark); text-decoration: none; }

.footer-bottom {
  max-width: var(--max-width);
  margin: 40px auto 0;
  padding-top: 24px;
  border-top: 1px solid var(--border);
  font-size: 12px;
  color: var(--gray);
  line-height: 1.6;
}

.footer-bottom p { margin-bottom: 8px; }

/* Store Difference */
.diff-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.diff-card {
  text-align: center;
  padding: 32px 20px;
}

.diff-icon {
  font-size: 40px;
  margin-bottom: 12px;
}

.diff-card h3 {
  font-size: 19px;
  font-weight: 600;
}

.diff-card p {
  font-size: 14px;
  color: var(--gray);
  margin-top: 6px;
}

/* Setup / Experience sections */
.setup-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.setup-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 32px 28px;
  box-shadow: var(--shadow);
}

.setup-card h3 {
  font-size: 21px;
  font-weight: 600;
}

.setup-card p {
  font-size: 14px;
  color: var(--gray);
  margin-top: 6px;
}

/* Special Stores */
.special-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.special-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 28px 24px;
  box-shadow: var(--shadow);
}

.special-card h3 {
  font-size: 17px;
  font-weight: 600;
}

.special-card p {
  font-size: 13px;
  color: var(--gray);
  margin-top: 4px;
}

/* Footer Accordion (Mobile) */
.footer-col h4 .accordion-arrow {
  display: none;
}

/* Responsive */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: 1fr 1fr; }
  .entertainment-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .savings-grid { grid-template-columns: repeat(2, 1fr); }
  .diff-grid { grid-template-columns: repeat(2, 1fr); }
  .special-grid { grid-template-columns: repeat(2, 1fr); }
  .guides-grid { grid-template-columns: repeat(2, 1fr); }
  .section-title { font-size: 36px; }
  .hero-title { font-size: 42px; }
}

@media (max-width: 768px) {
  .product-grid { grid-template-columns: 1fr; }
  .product-tile { min-height: 400px; }
  .entertainment-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .savings-grid { grid-template-columns: 1fr; }
  .diff-grid { grid-template-columns: 1fr; }
  .special-grid { grid-template-columns: 1fr; }
  .guides-grid { grid-template-columns: 1fr; }
  .setup-grid { grid-template-columns: 1fr; }
  .nav-links { display: none; }
  .nav-inner { justify-content: space-between; }
  .section-title { font-size: 32px; }
  .hero-title { font-size: 36px; }
  .hero-subtitle { font-size: 19px; }
  .section { padding: 48px 16px; }
  .section-header { margin-bottom: 32px; }
  .carousel-card { flex: 0 0 240px; }
  .tile-name { font-size: 24px; }
  .cat-hero-title { font-size: 32px; }

  /* Footer accordion */
  .footer-col h4 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 0;
    border-bottom: 1px solid var(--border);
    margin-bottom: 0;
  }
  .footer-col h4 .accordion-arrow {
    display: inline-block;
    transition: transform .2s;
    font-size: 14px;
  }
  .footer-col.open h4 .accordion-arrow { transform: rotate(45deg); }
  .footer-col ul { display: none; padding: 8px 0 16px; }
  .footer-col.open ul { display: block; }

  /* Mobile nav */
  .icon-bar { gap: 16px; padding: 16px; }
  .icon-circle { width: 48px; height: 48px; font-size: 22px; }
}

@media (max-width: 480px) {
  .carousel-card { flex: 0 0 200px; }
  .hero-ctas { flex-direction: column; align-items: center; }
  .collab-products { flex-direction: column; align-items: center; }
  .section-nav-inner { gap: 0; }
  .section-nav a { padding: 12px 14px; font-size: 12px; }
}

